    var mtdByCat = {}, lmByCat = {};
    pjCats().forEach(function (c) { mtdByCat[c[0]] = pjDailyMtd(rows, c[0], n); lmByCat[c[0]] = state.pjDse ? null : pjDailyMc(F, c[0], n).l; });
    var trs = '';
