    var rows = (F.products || []).filter(function (p) { return (b === 'all' || p.b === b) && (cat === 'all' || p.cat === cat) && (!q || (p.n + ' ' + p.b + ' ' + PJ_CAT_LABEL[p.cat]).toLowerCase().indexOf(q) !== -1); });
