      var outerKeys = Object.keys(outer).sort(function (x, y) { var ix = outerOrder.indexOf(x), iy = outerOrder.indexOf(y); return (ix < 0 ? 99 : ix) - (iy < 0 ? 99 : iy); });
      var singleOuter = outerKeys.length === 1 && (b !== 'all' || cat !== 'all');
