  /* ================= END BALANCE OUTLET (ENDBAL) ================= */
  var EB_BANDS = [['zero', 'Zero', 'bad'], ['lt50', '< 50K', 'warn'], ['b50', '50–100K', 'warn'], ['b100', '100–300K', 'ok'], ['b300', '≥ 300K', 'top']];
