    var sheets = Object.keys(g).map(function (k) { return g[k]; }).filter(function (x) { return x.day.length; }).sort(function (a, b) { return (a.br < b.br ? -1 : a.br > b.br ? 1 : 0) || (a.mc < b.mc ? -1 : a.mc > b.mc ? 1 : 0) || (a.dse < b.dse ? -1 : 1); });
