    if (!vf) return nav + card('Ringkasan Performance', '<p class="note">Feed kunjungan belum dimuat (jalankan <code>python3 scripts/generate_dse_visits_feed.py</code>).</p>');
    if (tab === 'pjp') return nav + mbPjpSection(vf);
